const multiBusyStates=['submitting','queued','running','waiting'];
function validImageSize(c){const size=c.imageSize||{width:512,height:1440};return [size.width,size.height].every(n=>Number.isInteger(n)&&n>=256&&n<=1536&&n%16===0)&&size.width*size.height<=1572864;}
function selectedFront(c){return c.versions?.[c.active];}
const withCharacterSettings=characters;
characters=function(){const c=data.characters[ci];if(c&&(!c.imageSize||(c.imageSize.width===512&&c.imageSize.height===768)))c.imageSize={...CharacterSheet.spec.view_sizes.front};if(c&&!c.multiPrompt)c.multiPrompt=CharacterSheet.spec.prompt;withCharacterSettings();if(!c)return;const generate=document.querySelector('#generate');if(!generate)return;c.imageSize??={width:512,height:1440};
const settings=document.createElement('div');const heading=document.createElement('div');heading.className='right-title';heading.textContent='生成尺寸';settings.append(heading);const presets=document.createElement('select');presets.setAttribute('aria-label','常用角色图尺寸');for(const [value,label] of [['512x1440','512 × 1440 · 全身推荐'],['512x768','512 × 768 · 竖图'],['768x1024','768 × 1024 · 竖图'],['768x768','768 × 768 · 方图'],['1024x1024','1024 × 1024 · 方图'],['1024x768','1024 × 768 · 横图'],['custom','自定义']]){const option=document.createElement('option');option.value=value;option.textContent=label;presets.append(option)}const current=c.imageSize.width+'x'+c.imageSize.height;presets.value=[...presets.options].some(x=>x.value===current)?current:'custom';presets.onchange=()=>{if(presets.value==='custom')return;const [width,height]=presets.value.split('x').map(Number);c.imageSize={width,height};save();render()};settings.append(presets);const row=document.createElement('div');row.className='field-row';for(const [key,label] of [['width','宽度 px'],['height','高度 px']]){const wrap=document.createElement('label');wrap.textContent=label;const input=document.createElement('input');input.type='number';input.dataset.imageSize='true';input.min='256';input.max='1536';input.step='16';input.value=c.imageSize[key];input.oninput=()=>{const n=Number(input.value);if(!Number.isInteger(n)||n<256||n>1536||n%16!==0){input.setCustomValidity('请使用 256–1536 之间的 16 倍数');return}input.setCustomValidity('');c.imageSize[key]=n;presets.value='custom';save()};wrap.append(input);row.append(wrap)}settings.append(row);const note=document.createElement('p');note.className='subtle';note.textContent='全身正面推荐 512×1440，可自定义；侧面和背面固定 512×1440，半身大头像固定 1024×1440。母图为 2560×1440，修改仅影响后续生成。尺寸为 16 的倍数；总像素最多约 157 万。修改只影响后续生成。';settings.append(note);generate.before(settings);
const isMulti=c.view==='multi',canMulti=c.confirmed&&c.confirmedVersion===c.active&&selectedFront(c)?.job_id;const entry=c.multi?.[c.multiActive??(c.multi.length-1)];const busy=entry?.jobs&&Object.values(entry.jobs).some(j=>multiBusyStates.includes(j.status));const multiButton=document.querySelector('#makeMulti');if(multiButton){multiButton.disabled=!canMulti||busy;multiButton.textContent=busy?'多面图正在生成…':'生成多面图';multiButton.title=canMulti?'使用已确认正面图生成半身大头像、单侧面和背面':'请先确认正面图';multiButton.onclick=()=>{c.view='multi';generateCharacter(true)}}
if(isMulti){for(const p of document.querySelectorAll('#panel p.subtle'))if(p.textContent.startsWith('正面图使用本机 Z-Image-Turbo'))p.textContent='人物多角度使用 Qwen-Image-Edit + Lightning LoRA，4步、CFG 1，引用人物身份图。';document.querySelector('a[href="/api/front-image-template"]')?.parentElement.remove();generate.disabled=!canMulti||busy;generate.textContent=busy?'多面图正在生成…':'✦ '+(entry?.jobs?'重新生成多面图':'生成多面图');const hint=document.createElement('p');hint.className='subtle';hint.textContent=canMulti?'自动使用已确认正面图与上方提示词，沿用已确定的大头像和已确认全身正面，仅生成单个90°侧面和背面。':'请先回到「正面图」，点击「确认正面形象」。';generate.after(hint);const preview=document.querySelector('.artboard');if(preview){preview.replaceChildren();preview.style.height='480px';const grid=document.createElement('div');grid.className='angle-grid';grid.style.gridTemplateColumns='2fr 1fr 1fr 1fr';for(const [angle,label] of [['portrait','正面半身大头像'],['front','全身正面'],['left','单个90°侧面'],['back','全身背面']]){const box=document.createElement('div');box.className='angle';const front=selectedFront(c)||(entry?.reference_job_id?c.versions.find(v=>v.job_id===entry.reference_job_id):null);const job=entry?.jobs?.[angle];const url=angle==='front'?front?.image_url:job?.image_url;if(url){const img=document.createElement('img');img.src=url;img.alt=c.name+' · '+label;img.style.cssText='width:100%;height:85%;object-fit:contain;background:#080d14';box.append(img)}else{const state=document.createElement('p');state.className='subtle';state.style.cssText='height:75%;display:grid;place-items:center';state.textContent=job?.status==='failed'?'失败：'+job.error:job?({submitting:'提交中',queued:'排队中',running:'生成中',waiting:'等待结果'})[job.status]||job.status:'待生成';box.append(state)}const caption=document.createElement('span');caption.textContent=label;box.append(caption);grid.append(box)}preview.append(grid)}const links=document.createElement('div');links.style.cssText='display:flex;gap:10px;flex-wrap:wrap;margin-top:12px;font-size:11px';for(const [label,href] of [['查看大头像模板','/api/front-image-template?mode=multiview&angle=portrait'],['查看多面图模板','/api/front-image-template?mode=multiview'],['下载模板','/api/front-image-template?mode=multiview&download=1']]){const a=document.createElement('a');a.textContent=label;a.href=href;a.target='_blank';a.style.color='var(--green)';links.append(a)}for(const [angle,label] of [['portrait','大头像'],['left','单侧面'],['back','背面']]){const job=entry?.jobs?.[angle];if(!job?.id)continue;const a=document.createElement('a');a.textContent=label+'实际工作流';a.href='/api/front-image/'+job.id+'/workflow';a.target='_blank';a.style.color='var(--green)';links.append(a)}generate.after(links);}}
const generateFrontOnly=generateCharacter;
generateCharacter=async function(multi){const c=data.characters[ci];if(!c)return;if([...document.querySelectorAll('[data-image-size]')].some(i=>!i.checkValidity())||!validImageSize(c)){toast('尺寸需为 256–1536 之间的 16 倍数，且总像素不超过约 157 万');return}if(!multi)return generateFrontOnly(false);const source=selectedFront(c);if(!c.confirmed||c.confirmedVersion!==c.active||!source?.job_id){toast('请先确认正面形象');return}if(c.multi?.some(v=>Object.values(v.jobs||{}).some(j=>multiBusyStates.includes(j.status)))){toast('已有多面图任务正在进行');return}const identity=c.identityPortrait||activeMulti(c)?.jobs?.portrait;if(identity?.status!=='completed'){toast('请先生成并确认大头像');return}const entry={time:new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'}),prompt:c.multiPrompt,reference_job_id:source.job_id,jobs:{portrait:{...identity,identity_master:true}}};c.multi??=[];c.multi.push(entry);c.multiActive=c.multi.length-1;c.view='multi';for(const angle of ['left','back'])entry.jobs[angle]={id:crypto.randomUUID(),status:'submitting'};save();render();for(const angle of ['left','back']){try{entry.jobs[angle]=await frontFetch('/api/front-image',{request_id:entry.jobs[angle].id,port:Number(localStorage.getItem('frame-comfy-port')||8188),mode:'multiview',angle,reference_job_id:source.job_id,project_id:data.project_id||data.title,character_id:c.id||c.character_id||c.name,character_name:c.name,background:c.nonWhiteBackground?'gray':'white',prompt:entry.prompt,...CharacterSheet.spec.view_sizes[angle]});}catch(e){entry.jobs[angle].status='failed';entry.jobs[angle].error=e.message}save();render()}toast('多面图任务已提交，请查看各角度状态')};
let multiPolling=false;setInterval(async()=>{if(multiPolling)return;multiPolling=true;let changed=false;try{for(const c of data.characters)for(const entry of c.multi||[])for(const [angle,job] of Object.entries(entry.jobs||{})){if(!['queued','running','waiting'].includes(job.status))continue;try{entry.jobs[angle]=await frontFetch('/api/front-image/'+job.id);changed=true;if(entry.jobs[angle].status==='completed'){c.reference_images??={};c.reference_images[angle]=entry.jobs[angle].image_url;}}catch(e){job.last_connection_error=e.message;}}if(changed){save();if(tab===0)render()}}finally{multiPolling=false}},3000);
document.querySelector('.notice').textContent='✦ 角色正面图与多面图已连接本机 ComfyUI；分镜、视频等后续环节仍待接入。';render();
